const featureNames = ['duration', 'protocol_type', 'service', 'flag', 'src_bytes', 'dst_bytes', 'land', 'wrong_fragment', 'urgent', 'hot', 'num_failed_logins', 'logged_in', 'num_compromised', 'root_shell', 'su_attempted', 'num_root', 'num_file_creations', 'num_shells', 'num_access_files', 'num_outbound_cmds', 'is_host_login', 'is_guest_login', 'count', 'srv_count', 'serror_rate', 'srv_serror_rate', 'rerror_rate', 'srv_rerror_rate', 'same_srv_rate', 'diff_srv_rate', 'srv_diff_host_rate', 'dst_host_count', 'dst_host_srv_count', 'dst_host_same_srv_rate', 'dst_host_diff_srv_rate', 'dst_host_same_src_port_rate', 'dst_host_srv_diff_host_rate', 'dst_host_serror_rate', 'dst_host_srv_serror_rate', 'dst_host_rerror_rate', 'dst_host_srv_rerror_rate'];
const label = s => s.replace(/^(remainder|cat)__([0-9]+)/, (_, kind, n) => featureNames[Number(n)]);
const pct = v => (v * 100).toFixed(3) + '%';
fetch('results.json').then(r => { if (!r.ok) throw Error('HTTP ' + r.status); return r.json() }).then(d => {
    document.querySelector('#dataset').textContent = `NSL-KDD KDDTrain+: ${d.train.toLocaleString('pt-BR')} conexões no treino e ${d.test.toLocaleString('pt-BR')} no teste. Ataques no teste: ${d.attacks_test.toLocaleString('pt-BR')} (${pct(d.attacks_test / d.test)}). A base não tem o desbalanceamento extremo comum em produção.`;
    document.querySelector('#rows').innerHTML = d.models.map(m => `<tr><td>${m.name}</td><td>${pct(m.accuracy)}</td><td>${pct(m.precision)}</td><td>${pct(m.recall)}</td><td>${pct(m.f1)}</td><td>${m.fit_s.toFixed(3)}</td><td>${m.single_ms.toFixed(3)}</td></tr>`).join('');
    document.querySelector('#bars').innerHTML = d.models.map(m => `<div>${m.name} <strong>${pct(m.f1)}</strong><div class="metric" role="img" aria-label="F1 de ${pct(m.f1)}"><i style="width:${m.f1 * 100}%"></i></div></div>`).join('');
    document.querySelector('#importance').innerHTML = d.models.map(m => `<article class="card"><h3>${m.name}</h3><ol>${m.importance.map(i => `<li><code>${label(i.feature)}</code>: ${(i.value * 100).toFixed(2)}%</li>`).join('')}</ol></article>`).join('');
    const select = document.querySelector('#model'); d.models.forEach((m, i) => select.add(new Option(m.name, i)));
    const draw = () => { let c = d.models[select.value].matrix; document.querySelector('#matrix').innerHTML = [['Normal → Normal', c[0][0], ''], ['Normal → Ataque (FP)', c[0][1], 'err'], ['Ataque → Normal (FN)', c[1][0], 'err'], ['Ataque → Ataque', c[1][1], '']].map(([label, v, cls]) => `<div class="${cls}">${label}<b>${v.toLocaleString('pt-BR')}</b></div>`).join('') }; select.onchange = draw; draw();
    document.querySelector('#timing').innerHTML = '<ul>' + d.models.map(m => `<li>${m.name}: busca + ajuste ${m.search_s.toFixed(2)} s; ajuste final ${m.fit_s.toFixed(2)} s; mediana individual ${m.single_ms.toFixed(3)} ms; p95 ${m.p95_ms.toFixed(3)} ms; lote ${m.batch_ms.toFixed(5)} ms/conexão. F1 na validação: ${pct(m.cv_f1)}.</li>`).join('') + '</ul>';
    document.querySelector('#environment').textContent = JSON.stringify(d.environment, null, 2) + '\nSHA-256: ' + d.sha256;
    const [dt, rf, xg] = d.models;
    document.querySelector('#verdict').innerHTML = `<span class="eyebrow">Recomendação neste experimento</span><h3>XGBoost, com uma vantagem pequena e mensurável.</h3><p>Vamos levar o XGBoost para a próxima validação: ele teve o maior F1 médio na validação (${pct(xg.cv_f1)}) e confirmou ${pct(xg.f1)} no teste. Foram ${xg.matrix[1][0]} ataques não detectados, contra ${dt.matrix[1][0]} na árvore e ${rf.matrix[1][0]} na floresta. Sua mediana individual foi ${xg.single_ms.toFixed(3)} ms, comparada aos ${dt.single_ms.toFixed(3)} ms da árvore e ${rf.single_ms.toFixed(3)} ms da floresta.</p><p>A floresta gerou menos falsos positivos (${rf.matrix[0][1]}, contra ${xg.matrix[0][1]} do XGBoost); se alertas indevidos forem o principal custo, ela merece preferência. A árvore é a escolha mais simples de explicar. O ganho de F1 do XGBoost sobre a floresta foi de apenas ${((xg.f1 - rf.f1) * 100).toFixed(3)} ponto percentual: sem intervalos de confiança, não afirmamos superioridade estatística.</p>`;
}).catch(() => { document.querySelector('#dataset').textContent = 'Não foi possível carregar os resultados. Consulte results.json no pacote do projeto.' });
